//! SQL generated by Ferrum for table browsing. Identifiers are always quoted
//! with the dialect's rules; no user data is interpolated.

use ferrum_domain::{DatabaseEngine, TableInfo};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BrowseQuery {
    pub sql: String,
    /// False when the table has no primary key: row order may change between runs.
    pub deterministic: bool,
}

/// `SELECT * FROM "schema"."table" ORDER BY <pk> LIMIT max_rows + 1`.
/// The extra row lets the driver detect truncation at `max_rows`.
#[must_use]
pub fn browse_query(engine: DatabaseEngine, info: &TableInfo, max_rows: usize) -> BrowseQuery {
    let mut sql = format!("SELECT * FROM {}", info.table.qualified(engine));
    let deterministic = !info.primary_key.is_empty();
    if deterministic {
        let cols: Vec<String> = info
            .primary_key
            .iter()
            .map(|c| engine.quote_ident(c))
            .collect();
        sql.push_str(&format!(" ORDER BY {}", cols.join(", ")));
    }
    sql.push_str(&format!(" LIMIT {}", max_rows.saturating_add(1)));
    BrowseQuery { sql, deterministic }
}

#[cfg(test)]
mod tests {
    use super::*;
    use ferrum_domain::{TableKind, TableRef};

    fn info(pk: &[&str]) -> TableInfo {
        TableInfo {
            table: TableRef {
                schema: Some("public".into()),
                name: "User".into(),
            },
            kind: TableKind::Table,
            primary_key: pk.iter().map(|s| (*s).to_owned()).collect(),
            estimated_rows: None,
        }
    }

    #[test]
    fn orders_by_quoted_primary_key() {
        let q = browse_query(DatabaseEngine::Postgres, &info(&["orgId", "id"]), 100);
        assert_eq!(
            q.sql,
            r#"SELECT * FROM "public"."User" ORDER BY "orgId", "id" LIMIT 101"#
        );
        assert!(q.deterministic);
    }

    #[test]
    fn no_primary_key_is_flagged_non_deterministic() {
        let q = browse_query(DatabaseEngine::Postgres, &info(&[]), 10);
        assert_eq!(q.sql, r#"SELECT * FROM "public"."User" LIMIT 11"#);
        assert!(!q.deterministic);
    }
}
